class ObjectManager(EMSSInterface):
    """
    EMSsim keywords related to objects management
    """
    ROBOT_LIBRARY_SCOPE = 'TEST SUITE'  # 'TEST CASE' 'GLOBAL'

    def __init__(self):
        super(ObjectManager, self).__init__()

    def _keys_lower(self, dictionary):
        return {key.lower(): value for key, value in list(dictionary.items())}

    def lock_object(self, object_name, retry_limit=3, retry_sleep=60, enb_id=None, bts_id=None, alias=None):
        """
        Changes administrative state of given object to locked.

        :param object_name: name of an object to lock
        :param retry_limit: Number of retries if failed (default=3)
        :param retry_sleep: Time in seconds between retries (default=60)
        :param bts_id (enb_id): BTS instance ID
        :param alias: User defined alias used in setup_emss

        +-------------+---------+
        |       Examples        |
        +=============+=========+
        | lock object | LNCEL-1 |
        +-------------+---------+
        | lock object | LNMME-0 |
        +-------------+---------+
        """
        retry_limit = self._opt_int(retry_limit)
        retry_sleep = self._opt_int(retry_sleep)
        bts_id = self._opt_id(enb_id, bts_id)

        self = self._get_instance(bts_id, alias)

        self.enb_configuration_should_be_discovered(bts_id=bts_id, alias=alias)

        lock_command = self._get_emssim().cmd_lock()
        command_succeeded = self._run_repeat_command(lock_command, object_name, retry_limit=retry_limit, retry_sleep=retry_sleep)
        self._assert(command_succeeded, "Lock %s operation failed" % object_name)

    def unlock_object(self, object_name, retry_limit=3, retry_sleep=60, enb_id=None, bts_id=None, alias=None):
        """
        Changes administrative state of given object to unlocked.

        :param object_name: name of an object to unlock
        :param retry_limit: Number of retries if failed (default=3)
        :param retry_sleep: Time in seconds between retries (default=60)
        :param bts_id (enb_id): BTS instance ID
        :param alias: User defined alias used in setup_emss

        +---------------+---------+
        |        Examples         |
        +===============+=========+
        | unlock object | LNCEL-1 |
        +---------------+---------+
        | unlock object | LNMME-0 |
        +---------------+---------+
        """
        retry_limit = self._opt_int(retry_limit)
        retry_sleep = self._opt_int(retry_sleep)
        bts_id = self._opt_id(enb_id, bts_id)

        self = self._get_instance(bts_id, alias)

        self.enb_configuration_should_be_discovered(bts_id=bts_id, alias=alias)

        unlock_command = self._get_emssim().cmd_unlock()
        command_succeeded = self._run_repeat_command(unlock_command, object_name, retry_limit=retry_limit, retry_sleep=retry_sleep)
        self._assert(command_succeeded, "Unlock %s operation failed" % object_name)

    def shutdown_object(self, object_name, retry_limit=3, retry_sleep=60, enb_id=None, bts_id=None, alias=None):
        """
        Performs shutdown on given object.

        :param object_name: name of an object to shut down
        :param retry_limit: Number of retries if failed (default=3)
        :param retry_sleep: Time in seconds between retries (default=60)
        :param bts_id (enb_id): BTS instance ID
        :param alias: User defined alias used in setup_emss

        +-----------------+---------+
        |          Examples         |
        +=================+=========+
        | shutdown object | LNCEL-1 |
        +-----------------+---------+
        | shutdown object | LNMME-0 |
        +-----------------+---------+
        """
        retry_limit = self._opt_int(retry_limit)
        retry_sleep = self._opt_int(retry_sleep)
        bts_id = self._opt_id(enb_id, bts_id)

        self = self._get_instance(bts_id, alias)

        self.enb_configuration_should_be_discovered(bts_id=bts_id, alias=alias)
        shutdown_command = self._get_emssim().cmd_shutdown()
        command_succeeded = self._run_repeat_command(shutdown_command, object_name, retry_limit=retry_limit, retry_sleep=retry_sleep)
        self._assert(command_succeeded, "Shutdown %s operation failed" % object_name)

    def all_cells_should_be_enabled(self, enb_id=None, bts_id=None, alias=None):
        """
        Verifies if all of the configured cell's Operational State is Enabled.

        :param bts_id (enb_id): BTS instance ID
        :param alias: User defined alias used in setup_emss

        +-----------------------------+
        |           Examples          |
        +=============================+
        | all cells should be enabled |
        +-----------------------------+
        """
        bts_id = self._opt_id(enb_id, bts_id)

        self = self._get_instance(bts_id, alias)

        all_cells = self.get_existing_objects_of_given_type("LNCEL", bts_id=bts_id, alias=alias)
        for cell in all_cells:
            self.object_state_should_be(cell, "OPERATIONAL", "enabled")

    def eNB_should_be_onAir(self, enb_id=None, bts_id=None, alias=None):
        """
        Verifies if LNBTS Operational State is onAir.

        :param bts_id (enb_id): BTS instance ID
        :param alias: User defined alias used in setup_emss

        +---------------------+
        |       Examples      |
        +=====================+
        | eNB should be onAir |
        +---------------------+
        """
        bts_id = self._opt_id(enb_id, bts_id)

        self = self._get_instance(bts_id, alias)

        self.object_state_should_be(self.get_LNBTS_object_name(), "OPERATIONAL", "onAir", bts_id=bts_id, alias=alias)

    def get_LNBTS_object_name(self, enb_id=None, bts_id=None, alias=None, silent=False):
        """
        Returns full name of LNBTS object (LNBTS-<ID>, e.g. 'LNBTS-88').

        :param bts_id (enb_id): BTS instance ID
        :param alias: User defined alias used in setup_emss
        :param silent: Do not print to console (default=False)

        +-----------+-----------------------+
        |             Examples              |
        +===========+=======================+
        | ${LNBTS}= | get LNBTS object name |
        +-----------+-----------------------+
        """
        bts_id = self._opt_id(enb_id, bts_id)

        self = self._get_instance(bts_id, alias)

        try:
            return self.get_existing_objects_of_given_type("LNBTS", bts_id=bts_id, alias=alias, silent=silent)[0]
        except Exception:
            pass

        try:
            return self.get_existing_objects_of_given_type("NRBTS", bts_id=bts_id, alias=alias, silent=silent)[0]
        except Exception:
            pass

        return None

    def object_state_should_be(self, object_name, state, value, enb_id=None, bts_id=None, alias=None):
        """
        Verifies if the given object's state equals the given value.

        :param object_name: Name of manageable object
        :param state: state name (ADMINISTRATIVE or OPERATIONAL)
        :param value: state's value to compare with
        :param bts_id (enb_id): BTS instance ID
        :param alias: User defined alias used in setup_emss

        +------------------------+---------+----------------+----------+
        |                            Examples                          |
        +========================+=========+================+==========+
        | object state should be | LNCEL-1 | ADMINISTRATIVE | unlocked |
        +------------------------+---------+----------------+----------+
        | object state should be | LNMME-0 | ADMINISTRATIVE |  locked  |
        +------------------------+---------+----------------+----------+
        | object state should be | LNBTS-7 |   OPERATIONAL  |  onAir   |
        +------------------------+---------+----------------+----------+
        """
        bts_id = self._opt_id(enb_id, bts_id)

        self = self._get_instance(bts_id, alias)

        self.enb_configuration_should_be_discovered(bts_id=bts_id, alias=alias)
        ls = self._get_emssim().cmd_ls()
        self._assert(ls.run(), "List states %s operation failed" % object_name)
        output = ls.returned_data()
        current_state = output['object_table'][object_name][state]
        self._assert(self._case_insensitive_stings_comparison(current_state, value), "%s %s state should be %s, but it's actually %s" %
                     (object_name, state, value, current_state))

    def get_object_state(self, object_name, state, enb_id=None, bts_id=None, alias=None):
        """
        Returns actual state of a given object.

        :param object_name: Name of manageable object
        :param state: state name (ADMINISTRATIVE or OPERATIONAL)
        :param bts_id (enb_id): BTS instance ID
        :param alias: User defined alias used in setup_emss
        :return: state's value (string)

        +------------------------+------------------+---------+----------------+
        |                              Examples                                |
        +========================+==================+=========+================+
        | ${object_state_value}= | get_object_state | LNCEL-1 | ADMINISTRATIVE |
        +------------------------+------------------+---------+----------------+
        | ${object_state_value}= | get_object_state | LNCEL-3 |  OPERATIONAL   |
        +------------------------+------------------+---------+----------------+
        """
        bts_id = self._opt_id(enb_id, bts_id)

        self = self._get_instance(bts_id, alias)

        self.enb_configuration_should_be_discovered(bts_id=bts_id, alias=alias)
        ls = self._get_emssim().cmd_ls()
        self._assert(ls.run(), "List states %s operation failed" % object_name)
        output = ls.returned_data()
        return output['object_table'][object_name][state]

    def edit_object_attributes_if_other_than(self, object_name, dictionary_of_attributes=None, enb_id=None, bts_id=None, alias=None, **kwargs):
        """
        Changes object's attributes in case they are not already set.

        See edit_object_attributes keyword for allowed params.
        """
        bts_id = self._opt_id(enb_id, bts_id)

        self = self._get_instance(bts_id, alias)

        if dictionary_of_attributes:
            self.edit_object_attributes_if_other_than(object_name, bts_id=bts_id, alias=alias,
                                                      **dict(self._keys_lower(dictionary_of_attributes), **self._keys_lower(kwargs)))
            return

        attributes_to_change = self._remove_attributes_already_configured(object_name, **kwargs)
        if attributes_to_change:
            self.edit_object_attributes(object_name, attributes_to_change, bts_id=bts_id, alias=alias)

    def _remove_attributes_already_configured(self, object_name, dictionary_of_attributes=None, **kwargs):
        if dictionary_of_attributes:
            return self._remove_attributes_already_configured(object_name, **dict(self._keys_lower(dictionary_of_attributes), **self._keys_lower(kwargs)))

        current_config = self.get_object_attributes(object_name)
        requested_config = self._keys_lower(kwargs)

        ret = {}
        for attribute, value in list(requested_config.items()):
            if not self._case_insensitive_stings_comparison(current_config[attribute], value):
                ret[attribute] = value
        return ret

    def edit_object_attributes(self, object_name, dictionary_of_attributes=None, retry_limit=3, retry_sleep=60,
                               enb_id=None, bts_id=None, alias=None, use_admin=False, **kwargs):
        """
        Changes values of object's atrributes.

        Be sure, that provided attribute is modifiable.

        :param object_name: (string) name of an object
        :param dictionary_of_attributes: (dict), dictionary containing attributes to change
            ({"attr1":value1, "attr2":value2, "attr3.fieldA":value3A})
        :param retry_limit: Number of retries if failed (default=3)
        :param retry_sleep: Time in seconds between retries (default=60)
        :param bts_id (enb_id): BTS instance ID
        :param alias: User defined alias used in setup_emss
        :param use_admin: Execute delta commissioning using ute_admin, if possible (i.e. no list params in kwargs)
        :param kwargs: one or more keyword argument describing attributes. Syntax:  key=value
            (eg.: attr1=value1    attr2=value2    attr3.field=value3, attr4.field[1]=value4),
            If no index specified, 0 will be taken (eg.: attr.field => attr.field[0])

        +------------------------+----------+-----------------------+------------------------------------+
        |                                            Examples                                            |
        +========================+==========+=======================+====================================+
        | edit object attributes | LNBTS-88 | qciTab1.schedulPrio=5 | mlbSpecialCase=adjustmentPreserved |
        +------------------------+----------+-----------------------+------------------------------------+
        | edit object attributes | LNMME-0  |              administrativeState=unlocked                  |
        +------------------------+----------+-----------------------+------------------------------------+
        | edit object attributes | LNCEL-1  |           sib2scheduling.simessagerepetition=1             |
        +------------------------+----------+-----------------------+------------------------------------+

        +----------------------------+------------------------+-----------------------------------------------------+---------------------+
        | Examples of usage 'dictionary_of_attributes' argument                                                                           |
        +============================+========================+=====================================================+=====================+
        | 1) Use values from configuration file                                                                                           |
        +----------------------------+------------------------+-----------------------------------------------------+---------------------+
        | edit object attributes     | LNREL-1-1              | dictionary_of_attributes=${dict_from_variable_file}                       |
        +----------------------------+------------------------+-----------------------------------------------------+---------------------+
        | 2) Use values from configuration file, with a little modifications                                                              |
        +----------------------------+------------------------+-----------------------------------------------------+---------------------+
        | edit object attributes     | LNREL-1-2              | dictionary_of_attributes=${dict_from_variable_file} |   ecgiAdjEnbId=91   |
        +----------------------------+------------------------+-----------------------------------------------------+---------------------+
        | 3) Revert object configuration                                                                                                  |
        +----------------------------+------------------------+-----------------------------------------------------+---------------------+
        |      ${lncel-1_attr}=      |  get_object_attributes |                        LNCEL-1                      | only_mandatory=True |
        +----------------------------+------------------------+-----------------------------------------------------+---------------------+
        |     # Some operations      |                                                                                                    |
        +----------------------------+------------------------+-----------------------------------------------------+---------------------+
        |   edit object attributes   |        LNCEL-1         |       dictionary_of_attributes=${lncel-1_attr}      |                     |
        +----------------------------+------------------------+-----------------------------------------------------+---------------------+
        """
        retry_limit = self._opt_int(retry_limit)
        retry_sleep = self._opt_int(retry_sleep)
        bts_id = self._opt_id(enb_id, bts_id)
        use_admin = self._opt_bool(use_admin) or self.use_admin

        self = self._get_instance(bts_id, alias)

        if dictionary_of_attributes:
            self.edit_object_attributes(object_name, bts_id=bts_id, alias=alias,
                                        **dict(self._keys_lower(dictionary_of_attributes), **self._keys_lower(kwargs)))
            return

        self.enb_configuration_should_be_discovered(bts_id=bts_id, alias=alias)
        self._clear_cache()
        self._wa_for_pdl_validation()

        plan_params = self._edit_to_plan(object_name, kwargs)

        if plan_params:
            print("Editing object by plan: {}".format(plan_params))
            self.configure(plan_params, skip_dc=True, use_admin=use_admin)
        else:
            params = self._parse_edit_params(object_name, kwargs)
            edit_command = self._get_emssim().cmd_edit()
            command_succeeded = self._run_repeat_command(edit_command, params, retry_limit=retry_limit, retry_sleep=retry_sleep)
            self._assert(command_succeeded, "Editing object's attributes %s operation failed" % object_name)

    def get_object_attributes_details(self, object_name, enb_id=None, bts_id=None, alias=None, silent=False):
        """
        Returns dictionary containing all object's attributes.

        :param object_name: (string) name of an object (with ID)
        :param bts_id (enb_id): BTS instance ID
        :param alias: User defined alias used in setup_emss
        :param silent: Do not print to console (default=False)
        :return: dictionary with object attributes
        """
        bts_id = self._opt_id(enb_id, bts_id)

        self = self._get_instance(bts_id, alias)

        attributes_details = self._get_cmd_attr_attributes_details(object_name, assert_run=True, silent=silent)
        return attributes_details

    def _get_attr_name(self, attr):
        return attr.split("[")[0]

    def _object_name_to_class(self, object_name):
        moi = object_name.split("/")[-1]
        srch_moc = re.search(r"^([^-]+)", moi)
        if srch_moc:
            return srch_moc.group(1)
        return moi

    def _is_not_set_by_system(self, attributes_details, attr):
        attr_name = self._get_attr_name(attr)
        if attr_name in attributes_details:
            return attributes_details[attr_name]['REQ'] != 'S'
        print(("Attribute %s not in NIDD. Assuming it is set-by-system" % str(attr_name)))
        # Workaround for eNB: Some Set-by-system attributes are consolidated from RUNTIME_VIEW
        # and may be present on eNB but not in NIDD
        return False

    def _is_mandatory(self, attributes_details, attr):
        attr_name = self._get_attr_name(attr)
        if attr_name in attributes_details:
            return attributes_details[attr_name]['REQ'] == 'M'
        print(("Attribute %s not in NIDD. Assuming it is not mandatory" % str(attr_name)))
        # Workaround for eNB: Some optional parameters may not be present in NIDD
        return False

    def _is_modifiable(self, attributes_details, attr):
        attr_name = self._get_attr_name(attr)
        if attr_name in attributes_details:
            return attributes_details[attr_name]['MOD'] == 'Y'
        print(("Attribute %s not in NIDD. Assuming it is unmodifiable" % str(attr_name)))
        # Workaround for eNB: Some unmodifiable attributes are consolidated from RUNTIME_VIEW
        # and may be present on eNB but not in NIDD
        return False

    def _name_to_moc_id(self, name):
        srch = re.search(r"([^\-]+)-(.*)", name)
        moc = None
        moid = None
        if srch:
            moc = srch.group(1)
            moid = srch.group(2)
        return (moc, moid)

    def _get_match_attr_name(self, attr_dict, name):
        if name in attr_dict:
            return name
        (moc, moid) = self._name_to_moc_id(name)
        for name_key in attr_dict:
            (key_moc, key_id) = self._name_to_moc_id(name_key)
            if key_moc == moc and key_id.endswith(moid):
                return name_key

        for name_key in attr_dict:
            match = re.match(name + '-.*', name_key)
            if match:
                return name_key
        print(("Cannot match moc key %s in dictionary %s" % (name, str(attr_dict))))

    def _get_migration_name(self, migration):
        for key in list(migration[0].keys()):
            if not key.isupper():
                return key.lower()
        return None

    def _get_if_migration(self, attr, moc, obj_id):
        to_migrate = {"MOC": moc, attr: None}
        if obj_id:
            to_migrate["ID"] = obj_id
        return self._get_om().migrate_moi(to_migrate)

    def _replace_migr_name_in_dict(self, arg, dictionary_to_return, migr_attr):
        dictionary_to_return[arg] = dictionary_to_return[migr_attr]
        dictionary_to_return.pop(migr_attr)
        return dictionary_to_return

    def _get_moc_and_id(self, object_name):
        try:
            moc, obj_id = object_name.split("-", 1)
        except ValueError:
            moc = object_name
            obj_id = None
        return moc, obj_id

    def _append_id_to_moc(self, migration, object_name):
        object_name += "-" + migration[0]["ID"] if "ID" in migration[0] else ""
        return object_name

    def _get_moc_name(self, migration):
        return migration[0]['MOC']

    def _perform_migration_process(self, attr, object_name):
        moc, obj_id = self._get_moc_and_id(object_name)
        migration = self._get_if_migration(attr, moc, obj_id)
        migr_attr = self._get_migration_name(migration)
        object_name = self._get_moc_name(migration)
        object_name = self._append_id_to_moc(migration, object_name)
        return migr_attr, object_name

    def _get_attr_list_values(self, attr, attributes):
        dict_val = {}
        for dict_attr in attributes:
            srch_simple = re.search(r'^([a-zA-Z0-9]+)\[(\d+)\]', dict_attr)
            srch_complex = re.search(r'^([a-zA-Z0-9]+)\.([a-zA-Z0-9]+)\[(\d+)\]', dict_attr)
            if srch_simple:
                dict_attr_name = srch_simple.group(1)
                dict_attr_id = srch_simple.group(2)
                if dict_attr_name == attr:
                    dict_val[dict_attr_id] = attributes[dict_attr]
            elif srch_complex:
                dict_attr_name = srch_complex.group(1)
                dict_subattr_name = srch_complex.group(2)
                dict_attr_id = srch_complex.group(3)
                if dict_attr_name == attr:
                    if dict_attr_id not in dict_val:
                        dict_val[dict_attr_id] = {}
                    dict_val[dict_attr_id][dict_subattr_name] = attributes[dict_attr]
        return [dict_val[key] for key in sorted(dict_val.keys(), key=int)]

    def get_object_attributes(self, object_name, *args, **kwargs):
        """
        Returns dictionary containing object's attributes. \
        If no args are specified returned dictionary contains all of object's attributes.

        :param object_name: (string) name of an object (with ID)
        :param args: (list of strings) optional - names of requested attributes
        :param bts_id (enb_id): BTS instance ID
        :param alias: User defined alias used in setup_emss
        :param silent: Do not print to console (default=False)
        :param kwargs: (key=value type) optional - flags limiting number of returned attributes. Possible flags are:
            without_set_by_system=True/False, default=False,
            only_mandatory=True/False, default=False,
            only_modifiable=True/False, default=False.

        +----------------+------------------------+----------+----------------+---------------------+
        |                                           Examples                                        |
        +================+========================+==========+================+=====================+
        | ${cell1_attr}= |  get object attributes | LNCEL-1  |                                      |
        +----------------+------------------------+----------+----------------+---------------------+
        | ${lnbts_attr}= |  get object attributes | LNBTS-88 |        @{LIST_OF_ATTRIBUTES}         |
        +----------------+------------------------+----------+----------------+---------------------+
        | ${lnbts_attr}= |  get object attributes | LNBTS-88 | mlbspecialcase | ACTINTRAFREQLOADBAL |
        +----------------+------------------------+----------+----------------+---------------------+
        | ${cell1_attr}= |  get object attributes | LNCEL-1  |      loadsettings.cellCapClass       |
        +----------------+------------------------+----------+----------------+---------------------+
        | ${cell1_attr}= |  get object attributes | LNCEL-1  |      without_set_by_system=True      |
        +----------------+------------------------+----------+----------------+---------------------+
        | ${cell1_attr}= |  get object attributes | LNCEL-1  |          only_mandatory=True         |
        +----------------+------------------------+----------+----------------+---------------------+
        """
        bts_id = kwargs.pop('bts_id', None)
        enb_id = kwargs.pop('enb_id', None)
        alias = kwargs.pop('alias', None)
        silent = kwargs.pop('silent', False)
        bts_id = self._opt_id(enb_id, bts_id)

        self = self._get_instance(bts_id, alias)

        self.enb_configuration_should_be_discovered(bts_id=bts_id, alias=alias)
        migr_attr = None

        if len(args) == 1:
            try:
                migr_attr, obj_name = self._perform_migration_process(args[0], object_name)
                if migr_attr and obj_name:
                    object_name = obj_name
            except Exception as exc:
                print(("Cannot migrate %s (%s). Migration not used." % (args[0], str(exc))))

        attributes = self._get_cmd_disp_all_attributes(object_name, silent=silent)
        self._assert(attributes, "Displaying %s attributes operation failed" % object_name)
        all_attributes_dictionary = self._keys_lower(attributes[self._get_match_attr_name(attributes, object_name.upper())])
        dictionary_to_return = all_attributes_dictionary

        if args:
            dictionary_to_return = self._filter_chosen_args(args,
                                                            all_attributes_dictionary,
                                                            migr_attr)
        if kwargs:
            without_set_by_system = kwargs.get('without_set_by_system', False)
            only_mandatory = kwargs.get('only_mandatory', False)
            only_modifiable = kwargs.get('only_modifiable', False)
            dictionary_to_return = self._filter_object_attributes(object_name,
                                                                  dictionary_to_return,
                                                                  without_set_by_system,
                                                                  only_mandatory,
                                                                  only_modifiable,
                                                                  silent=silent)
        return dictionary_to_return

    def wait_for_object_attribute_value(self, object_name, attribute_name, value=None, min_value=None, max_value=None,
                                        timeout=300, enb_id=None, bts_id=None, alias=None):
        """
        Wait for a given object attribute value or for a value in a given min and max range.

        :param object_name: (string) name of an object (with ID)
        :param attribute_name: (string) name of an attribute
        :param value: exact value to wait for
        :param min_value (integer): minimum object attribute value to wait for
        :param max_value (integer): maximum object attribute value to wait for
        :param timeout (integer): maximum time in seconds to wait for a given attribute value, default=300
        :param bts_id (enb_id): BTS instance ID
        :param alias: User defined alias used in setup_emss

        +---------------------------------+----------------+--------------------------------+--------------+--------------+
        |                                           Examples                                                              |
        +=================================+================+================================+==============+==============+
        | wait for object attribute value | LNMME-0        | s1LinkStatus                   | value=available             |
        +---------------------------------+----------------+--------------------------------+--------------+--------------+
        | wait for object attribute value | ANTL_R-1-1-1-1 | antennaPathDelayDL             | min_value=20 | max_value=30 |
        +---------------------------------+----------------+--------------------------------+--------------+--------------+
        | wait for object attribute value | LNBTS-1        | qciTabOperator.counterGroup[0] | 20                          |
        +---------------------------------+----------------+--------------------------------+--------------+--------------+
        | wait for object attribute value | TOPF-1-1       | acceptedClockQuality[3]        | 14                          |
        +---------------------------------+----------------+--------------------------------+--------------+--------------+
        """
        min_value = self._opt_int(min_value)
        max_value = self._opt_int(max_value)
        timeout = self._opt_int(timeout)
        bts_id = self._opt_id(enb_id, bts_id)

        self = self._get_instance(bts_id, alias)

        val = value if value is not None else "[{} {}]".format(min_value, max_value)
        print("Waiting for {} {} value '{}' up to {} seconds".format(object_name, attribute_name, val, timeout))

        is_value = False
        start_time = time.time()
        while time.time() - start_time < timeout:
            is_value = self._check_object_attribute_value(object_name, attribute_name, value, min_value, max_value)
            if is_value:
                break
            self._wait_for_ccn(timeout)

        if not is_value:
            self.discover_bts()
            is_value = self._check_object_attribute_value(object_name, attribute_name, value, min_value, max_value)
        self._assert(is_value, "Timeout waiting for parameter value: {} {}: '{}'".format(object_name, attribute_name, val))

    def get_incoming_ccn_message(self, object_name=None, timeout=300, enb_id=None, bts_id=None, alias=None):
        """
        Returns dictionary containing CCN message with provided object's name. \
        If no args are specified returned dictionary contains all CCN message.

        :param object_name: (string) name of an object
        :param timeout (integer): maximum time in seconds to wait for a given attribute value, default=300
        :param bts_id (enb_id): BTS instance ID
        :param alias: User defined alias used in setup_emss

        +---------------------------------+----------------+
        |                           Examples               |
        +=================================+================+
        | get incoming ccn message        | NRCELL         |
        +---------------------------------+----------------+

        """
        timeout = self._opt_int(timeout)
        bts_id = self._opt_id(enb_id, bts_id)

        self = self._get_instance(bts_id, alias)

        ccn_message = self._wait_for_ccn(timeout)
        parsed_ccn = self._parse_xml_list_to_list_of_dicts_xmltodict(ccn_message)

        if object_name:
            filtered_list = []
            for item in parsed_ccn:
                if 'class' in item and isinstance(item['class'], str) and item['class'].split(':')[-1] == object_name:
                    filtered_list.append(item)
            return filtered_list
        return parsed_ccn

    def _parse_xml_list_to_list_of_dicts_xmltodict(self, xml_string_list):
        all_managed_objects_data = []
        seen_dicts_json = set()

        for xml_string in xml_string_list:
            if not xml_string:
                continue

            try:
                parsed_dict = xmltodict.parse(xml_string)
            except Exception as e:
                print(f"Error parsing XML string: {e}")
                continue

            cm_data = parsed_dict.get('raml', {}).get('cmData', {})
            managed_objects_raw = cm_data.get('managedObject')

            if not isinstance(managed_objects_raw, list):
                managed_objects_raw = [managed_objects_raw] if managed_objects_raw else []

            for mo_raw in managed_objects_raw:
                if mo_raw:
                    mo_dict = {
                        'distName': mo_raw.get('@distName'),
                        'class': mo_raw.get('@class'),
                        'version': mo_raw.get('@version'),
                        'operation': mo_raw.get('@operation'),
                        'parameters': {}
                    }

                    params_raw = mo_raw.get('p')
                    if params_raw:
                        if not isinstance(params_raw, list):
                            params_raw = [params_raw]

                        for p_item in params_raw:
                            if p_item and '@name' in p_item:
                                param_name = p_item['@name']
                                param_value = p_item.get('#text')
                                mo_dict['parameters'][param_name] = param_value

                    mo_dict_json = json.dumps(mo_dict, sort_keys=True)

                    if mo_dict_json not in seen_dicts_json:
                        seen_dicts_json.add(mo_dict_json)
                        all_managed_objects_data.append(mo_dict)

        return all_managed_objects_data

    def _check_object_attribute_value(self, object_name, attribute_name, value, min_value, max_value):
        value = self._convert_bool(value)
        try:
            values = self.get_object_attributes(object_name, attribute_name)
            curr_value = values.get(attribute_name.lower())
            curr_value = self._convert_bool(curr_value)
            print("Object attribute values=%s" % values)
            print("Current object attribute value=%s" % curr_value)
            if value is not None and self._check_attribute_value(curr_value, str(value)):
                print("Attribute '{}' has value '{}'".format(attribute_name, curr_value))
                return True

            if self._check_attribute_value_range(curr_value, min_value, max_value):
                print("Attribute '{}' value '{}' within range: [{} {}]".format(attribute_name, curr_value, min_value, max_value))
                return True
        except Exception as exc:
            print("Cannot check attribute value: {}".format(exc))
        return False

    def _convert_bool(self, value):
        if value is True:
            return 'true'
        if value is False:
            return 'false'
        try:
            if value.lower() == 'true':
                return 'true'
            if value.lower() == 'false':
                return 'false'
        except Exception:
            pass
        return value

    def _wait_for_ccn(self, timeout):
        print("Waiting for CCN up to %s seconds" % timeout)
        self._get_emssim().subscribe_events(event_type='ccn')
        ccn = None
        start_time = time.time()
        while time.time() - start_time < timeout:
            ccn = self._get_emssim().get_events(event_type='ccn')
            if ccn:
                print("Got CCN after %s seconds" % (time.time() - start_time))
                break
            time.sleep(1)
        self._get_emssim().unsubscribe_events(event_type='ccn')
        return ccn

    def _check_attribute_value(self, curr_value, value):
        if value is None:
            return False
        if curr_value != value:
            return False
        return True

    def _check_attribute_value_range(self, curr_value, min_value, max_value):
        if min_value is None and max_value is None:
            return False
        curr_value_int = int(curr_value)
        if min_value is not None:
            if curr_value_int < min_value:
                return False
        if max_value is not None:
            if curr_value_int > max_value:
                return False
        return True

    def _filter_chosen_args(self, args, all_attributes_dictionary, migr_attr):
        chosen_args = []
        for arg in args:
            if "." in arg and "[" not in arg:
                chosen_args.append(arg.lower() + "[0]")
            else:
                if migr_attr:
                    arg = migr_attr
                chosen_args.append(arg.lower())

        try:
            dictionary_to_return = {}
            for attr in chosen_args:
                if attr in all_attributes_dictionary:
                    dictionary_to_return[attr] = all_attributes_dictionary[attr]
                else:
                    list_values = self._get_attr_list_values(attr, all_attributes_dictionary)
                    if list_values:
                        dictionary_to_return[attr] = list_values
                    else:
                        raise KeyError(attr)

            if migr_attr:
                arg = args[0].lower()
                if arg != migr_attr:
                    dictionary_to_return = self._replace_migr_name_in_dict(arg, dictionary_to_return, migr_attr)
        except KeyError as e:
            print(("At least one of provided attributes does not belong to the object. Invalid attribute: %s" % str(e)))
            raise

        return dictionary_to_return

    def _filter_object_attributes(self, object_name, dictionary_to_return, without_set_by_system, only_mandatory, only_modifiable, silent=False):
        attributes_details = self._get_cmd_attr_attributes_details(object_name, silent=silent)

        if without_set_by_system:
            dictionary_to_return = {a: v for a, v in list(dictionary_to_return.items()) if self._is_not_set_by_system(attributes_details, a)}

        if only_mandatory:
            dictionary_to_return = {a: v for a, v in list(dictionary_to_return.items()) if self._is_mandatory(attributes_details, a)}

        if only_modifiable:
            dictionary_to_return = {a: v for a, v in list(dictionary_to_return.items()) if self._is_modifiable(attributes_details, a)}

        return dictionary_to_return

    def _get_cmd_attr_attributes_details(self, object_name, assert_run=False, silent=False):
        object_class = self._object_name_to_class(object_name)

        attributes_details = {}
        if object_class in self.cmd_attr_attributes_details:
            attributes_details = self.cmd_attr_attributes_details[object_class]
        else:
            attr_cmd = self._get_emssim().cmd_attr()
            func = attr_cmd.run_silently if silent else attr_cmd.run
            cmd_status = func(object_class)
            if assert_run:
                self._assert(cmd_status, "Downloading detailed data of %s attributes operation failed" % object_class)
            returned_data = attr_cmd.returned_data()
            if 'attributes_details' in returned_data:
                attributes_details = self._keys_lower(returned_data['attributes_details'])
                self.cmd_attr_attributes_details[object_class] = attributes_details
        return attributes_details

    def _get_cmd_disp_all_attributes(self, object_name, silent=False):
        object_name = object_name.upper()
        attributes = {}
        try:
            disp_all = self._get_emssim().cmd_disp_all()
            func = disp_all.run_silently if silent else disp_all.run
            if func(object_name):
                disp_all_output = disp_all.returned_data()
                attributes = disp_all_output['attributes']
        except Exception:
            pass
        return attributes

    def get_values_of_structural_attribute(self, object_name, attribute, lower_values=True, can_fail=False, enb_id=None, bts_id=None, alias=None, silent=False):
        """
        Returns dictionary containing obejct's attributes.

        :param object_name: Object name with ID
        :param attribute: attribute name
        :param lower_values: normalize returned values to lowercase (default=True)
        :param can_fail: do not run on failure actions (default=False)
        :param bts_id (enb_id): BTS instance ID
        :param alias: User defined alias used in setup_emss
        :param silent: Do not print to console (default=False)
        :return: array of dictionaries

        +--------------+--------------------------------------+---------+--------------------+
        |                                       Examples                                     |
        +==============+======================================+=========+====================+
        | @{values}=   | get_values_of_structural_attribute   | LNMME-0 |  accMmePlmnsList   |
        +--------------+--------------------------------------+---------+--------------------+
        """
        lower_values = self._opt_bool(lower_values)
        bts_id = self._opt_id(enb_id, bts_id)

        self = self._get_instance(bts_id, alias)

        object_name = str(object_name).upper()
        attribute = str(attribute).lower()
        disp = self._get_emssim().cmd_disp(lower_values=lower_values)
        func = disp.run_silently if silent else disp.run
        self._assert(func(object_name, attribute), "Displaying %s:%s values failed" % (object_name, attribute), can_fail=can_fail)
        return disp.returned_data()['attributes'][object_name][attribute]

    def check_if_attribute_exists(self, object_name, attribute, enb_id=None, bts_id=None, alias=None, silent=False):
        """
        Verifies if object with given attributes exists.

        :param object_name: (string) name of an object (with ID)
        :param attribute: name of an attribute
        :param bts_id (enb_id): BTS instance ID
        :param alias: User defined alias used in setup_emss
        :param silent: Do not print to console (default=False)
        :return: 1 if exists, 0 if not exist

        +--------------+---------------------------+----------+------------------------------+
        |                                       Examples                                     |
        +==============+===========================+==========+==============================+
        | ${is_exist}= | check_if_attribute_exists |  lncel-1 |         loadsettings         |
        +--------------+---------------------------+----------+------------------------------+
        | ${is_exist}= | check_if_attribute_exists | LNBTS-88 | qciTabOperator.schedulWeight |
        +--------------+---------------------------+----------+------------------------------+
        """
        bts_id = self._opt_id(enb_id, bts_id)

        self = self._get_instance(bts_id, alias)

        object_name = str(object_name).upper()
        attribute = str(attribute).lower()
        self.enb_configuration_should_be_discovered(bts_id=bts_id, alias=alias)
        attributes = self._get_cmd_disp_all_attributes(object_name, silent=silent)

        try:
            all_attributes_dictionary = self._keys_lower(attributes[object_name.upper()])
        except KeyError:
            print("Provided object doesn't exist")
            return 0

        for key in list(all_attributes_dictionary.keys()):
            if (attribute + ".") in key or (attribute + '[0]') in key:
                return 1

        if attribute not in all_attributes_dictionary or all_attributes_dictionary[attribute] == "":
            print("Provided attribute doesn't exist")
            return 0

        return 1

    def check_if_object_exists(self, object_name, enb_id=None, bts_id=None, alias=None, silent=False):
        """
        Verifies if object with given name exists.

        :param object_name: (string) name of an object (with ID)
        :param bts_id (enb_id): BTS instance ID
        :param alias: User defined alias used in setup_emss
        :param silent: Do not print to console (default=False)
        :return: 1 if exists, 0 if not exist

        +--------------+------------------------+-------------+
        |                       Examples                      |
        +==============+========================+=============+
        | ${is_exist}= | check_if_object_exists |   lncel-1   |
        +--------------+------------------------+-------------+
        | ${is_exist}= | check_if_object_exists | lnrel-1-198 |
        +--------------+------------------------+-------------+
        """
        bts_id = self._opt_id(enb_id, bts_id)

        self = self._get_instance(bts_id, alias)

        object_name = object_name.upper()
        self.enb_configuration_should_be_discovered(bts_id=bts_id, alias=alias)
        attributes = self._get_cmd_disp_all_attributes(object_name, silent=silent)

        if object_name in attributes and attributes[object_name] is not None:
            return 1
        return 0

    def get_object_id(self, moc, silent=False, enb_id=None, bts_id=None, alias=None):
        """
        Return integer number of the singleton object ID of a given moc. Return None if no such object.
        Throw exception if the given moc is not a singleton.

        :param moc: (string) managed object class - eg. MRBTS
        :param silent: Do not throw exception if moc not found (default=False)
        :param silent: (string) managed object class - eg. MRBTS
        :param bts_id (enb_id): BTS instance ID
        :param alias: User defined alias used in setup_emss
        :param silent: Do not print to console (default=False)

        +----------------------+------------------+---------+
        |                    Examples                       |
        +======================+==================+=========+
        |     ${mrbts_id}=     | get_object_id    |  MRBTS  |
        +----------------------+------------------+---------+
        """
        bts_id = self._opt_id(enb_id, bts_id)
        silent = self._opt_bool(silent)
        moc = moc.upper()

        self = self._get_instance(bts_id, alias)

        self.enb_configuration_should_be_discovered(bts_id=bts_id, alias=alias)

        objects = self.get_existing_objects_of_given_type(moc, bts_id=bts_id, alias=alias, silent=silent)
        if len(objects) > 1 and not silent:
            raise Exception("MOC {} not a singleton: found {} instances)".format(moc, len(objects)))
        for obj in objects:
            srch = re.search(r'(\d+)$', obj)
            if srch:
                return int(srch.group(1))
        if not silent:
            print("Object of given type doesn't exist (%s)" % moc)
        return None

    def get_existing_objects_of_given_type(self, type_of_objects, enb_id=None, bts_id=None, alias=None, silent=False):
        """
        Returns list of names of existing objects, specified by type_of_objects argument.

        Keyword fails if there is no objects of that type on eNB.

        :param type_of_objects: (string) object's type - eg. LNCEL
        :param bts_id (enb_id): BTS instance ID
        :param alias: User defined alias used in setup_emss
        :param silent: Do not print to console (default=False)

        +----------------------+------------------------------------+---------+
        |                                 Examples                            |
        +======================+====================================+=========+
        |     @{all_cells}=    | get_existing_objects_of_given_type |  lncel  |
        +----------------------+------------------------------------+---------+
        |   @{all_relations}=  | get_existing_objects_of_given_type |  lnrel  |
        +----------------------+------------------------------------+---------+
        | @{relations_lncel1}= | get_existing_objects_of_given_type | lnrel-1 |
        +----------------------+------------------------------------+---------+
        """
        bts_id = self._opt_id(enb_id, bts_id)

        self = self._get_instance(bts_id, alias)

        self.enb_configuration_should_be_discovered(bts_id=bts_id, alias=alias)

        attributes = self._get_cmd_disp_all_attributes(type_of_objects, silent=silent)
        if attributes:
            return sorted(attributes.keys())
        if not silent:
            print("Objects of given type don't exist or executing command disp_all failed for %s" % type_of_objects)
        return []

    def object_attributes_should_be(self, object_name, dictionary_of_attributes=None, enb_id=None, bts_id=None, alias=None, **kwargs):
        """
        Verifies if object's attributes have given values.

        :param object_name: (string) name of an object
        :param dictionary_of_attributes: (dict) optional, dictionary containing attributes to check
            ({"attr1":value1, "attr2":value2, "attr3.fieldA":value3A})
        :param bts_id (enb_id): BTS instance ID
        :param alias: User defined alias used in setup_emss
        :param kwargs: one or more keyword argument describing attributes.
            Syntax:  key=value (attr1=value1    attr2=value2    attr3.fieldA=value3A).

        +-----------------------------+-----------+------------------+------------------------------------------------+
        |                                                  Examples                                                   |
        +=============================+===========+==================+================================================+
        | Object Attributes Should Be | LNCEL-1   | ulpcPuschConfig.ulpcLowlevSch=-103                                |
        +-----------------------------+-----------+------------------+------------------------------------------------+
        | Object Attributes Should Be | LNREL-200 | ecgiAdjEnbId=66  |  ecgiLcrId=3                                   |
        +-----------------------------+-----------+------------------+------------------------------------------------+
        | Object Attributes Should Be | LNBTS-88  | dictionary_of_attributes=${dict_of_attributes_from_variable_file} |
        +-----------------------------+-----------+------------------+------------------------------------------------+
        """
        bts_id = self._opt_id(enb_id, bts_id)

        self = self._get_instance(bts_id, alias)

        if dictionary_of_attributes:
            self.object_attributes_should_be(object_name, **dict(self._keys_lower(dictionary_of_attributes), **self._keys_lower(kwargs)))
            return

        object_name = str(object_name).lower()

        self.enb_configuration_should_be_discovered(bts_id=bts_id, alias=alias)
        all_attributes = self.get_object_attributes(object_name, bts_id=bts_id, alias=alias)

        for attribute, value in list(kwargs.items()):
            value = str(value)
            attribute = attribute.lower()
            if "." in attribute and "[" not in attribute:
                attribute = attribute + "[0]"
            try:
                current_value = all_attributes[attribute]
            except KeyError as e:
                print(("At least one of provided attributes does not belong to the object. Invalid attribute: %s" % str(e)))
                raise
            self._assert(self._case_insensitive_stings_comparison(current_value, value),
                         "Wrong value! Object's: %s attribute: %s should be %s, but it's actually %s" %
                         (object_name, attribute, value, current_value))

    def delete_object_attribute(self, object_name, attribute, retry_limit=3, retry_sleep=60, enb_id=None, bts_id=None, alias=None):
        """
        Deletes structural attribute of existing object. This keyword deletes all instances of this attribute.

        :param object_name: (string) name of the existing object
        :param attribute: (string) name of structural attribute to delete
        :param retry_limit: Number of retries if failed (default=3)
        :param retry_sleep: Time in seconds between retries (default=60)
        :param bts_id (enb_id): BTS instance ID
        :param alias: User defined alias used in setup_emss

        +-------------------------+---------+-----------------+
        |                         Examples                    |
        +=========================+=========+=================+
        | delete_object_attribute | LNCEL-1 |   loadsettings  |
        +-------------------------+---------+-----------------+
        | delete_object_attribute | LNCEL-2 | moprmappinglist |
        +-------------------------+---------+-----------------+
        """
        retry_limit = self._opt_int(retry_limit)
        retry_sleep = self._opt_int(retry_sleep)
        bts_id = self._opt_id(enb_id, bts_id)

        self = self._get_instance(bts_id, alias)

        self._wa_for_pdl_validation()

        params = "%s %s []" % (object_name, attribute)
        edit_command = self._get_emssim().cmd_edit()
        command_succeeded = self._run_repeat_command(edit_command, params, retry_limit=retry_limit, retry_sleep=retry_sleep)
        self._assert(command_succeeded, "Edit command failed")

    def get_indexes_of_list_elements_of_structural_attribute(self, object_name, attribute, dictionary_of_subattributes=None,
                                                             enb_id=None, bts_id=None, alias=None, **kwargs):
        """
        Returns list of indexes corresponding to records in structural paremeter where subattributes and values are matching \
        with the ones specified in dictionary_of_subattributes argument.

        :param object_name: (string) name of the existing object
        :param attribute: (string) name of structural attribute
        :param dictionary_of_subattributes: (dict) optional, dictionary containing subattributes to check ({"attr1":value1, "attr2":value2})
        :param bts_id (enb_id): BTS instance ID
        :param alias: User defined alias used in setup_emss
        :param kwargs: one or more keyword arguments describing subattributes. Syntax:  key=value (attr1=value1    attr2=value2)

        +-------------+------------------------------------------------------+----------+----------------+---------------------+
        |                                                  Examples                                                            |
        +=============+======================================================+==========+================+=====================+
        |indexes_list | get_indexes_of_list_elements_of_structural_attribute | LNBTS-11 | qciTabOperator |   qciSupp='ENABLE'  |
        +-------------+------------------------------------------------------+----------+----------------+---------------------+
        |indexes_list | get_indexes_of_list_elements_of_structural_attribute | LNBTS-11 | qciTabOperator | {'qciSupp':'ENABLE'}|
        +-------------+------------------------------------------------------+----------+----------------+---------------------+
        """
        bts_id = self._opt_id(enb_id, bts_id)

        self = self._get_instance(bts_id, alias)

        if dictionary_of_subattributes:
            return self.get_indexes_of_list_elements_of_structural_attribute(object_name, attribute, bts_id=bts_id, alias=alias,
                                                                             **dict(dictionary_of_subattributes, **kwargs))

        self.enb_configuration_should_be_discovered()
        structural_attribute_record_list = self.get_values_of_structural_attribute(object_name, attribute, bts_id=bts_id, alias=alias)
        s_attr = EmssStructuralAttribute(object_name, attribute, structural_attribute_record_list)
        return s_attr.get_indexes_of_matching_subattributes_records(**kwargs)

    def translate_scfc_value_to_user_interface_format(self, object_name, attribute, value, enb_id=None, bts_id=None, alias=None):
        """
        Translates given object's attribute value in CCN to User Interface.

        :param object_name: Object name
        :param attribute: Attribute name
        :param value: Objects attribute value
        :param bts_id (enb_id): BTS instance ID
        :param alias: User defined alias used in setup_emss
        :return: translated value

        +------------------------+-----------------------------------------------+----------+---------------------+------------+
        |                                                        Examples                                                      |
        +========================+===============================================+==========+=====================+============+
        |  ${translated_value}=  | translate_scfc_value_to_user_interface_format | LNCEL-1  | timeToTriggerSfHigh |  ${value}  |
        +------------------------+-----------------------------------------------+----------+---------------------+------------+
        """
        bts_id = self._opt_id(enb_id, bts_id)

        self = self._get_instance(bts_id, alias)

        cmd = self._get_emssim().cmd_scfc_value_to_ui()
        self._assert(cmd.run(object_name, attribute, value), "Cannot translate value")
        return cmd.returned_data()[attribute]

    def get_enb_parameter_value(self, moc_object, parameter, enb_id=None, bts_id=None, alias=None):
        """
        Returns given parameter value

        :param moc_object: MOC with ID
        :param parameter: parameter name
        :param bts_id (enb_id): BTS instance ID
        :param alias: User defined alias used in setup_emss
        :return: configured value

        +-------------------------+---------+-----------------+------------+
        | Examples                                                         |
        +=========================+=========+=================+============+
        | get enb parameter value | LNCEL-1 | inactivityTimer | bts_id=1   |
        +-------------------------+---------+-----------------+------------+
        """
        bts_id = self._opt_id(enb_id, bts_id)

        self = self._get_instance(bts_id, alias)

        return self.get_object_attributes(moc_object, parameter, bts_id=bts_id, alias=alias)[str(parameter).lower()]

    def set_enb_parameter_value(self, param_path, value, enb_id=None, bts_id=None, alias=None):
        """
        Set value of variable (eNB parameter) declared in yaml config file.

        :param param_path: path to parameter
        :param value: parameter value
        :param bts_id (enb_id): BTS instance ID
        :param alias: User defined alias used in setup_emss
        :return: None

        +--------------------------+--------------------------+------+----------+
        |  Examples                                                             |
        +==========================+==========================+======+==========+
        | set enb parameter value  | LNBTS-1.act1xSrvcc       | true | bts_id=1 |
        +--------------------------+--------------------------+------+----------+
        | set enb parameter value  | LNCEL-1.inactivityTimer  | 120  | bts_id=2 |
        +--------------------------+--------------------------+------+----------+
        """
        bts_id = self._opt_id(enb_id, bts_id)

        self = self._get_instance(bts_id, alias)

        self.set(param_path, value, bts_id=bts_id)

    def verify_that_enb_parameter_is_set_to_expected_value(self, moc_object, parameter, expected_value, discover=False,
                                                           enb_id=None, bts_id=None, alias=None):
        """

        :param moc_object: MOC with ID
        :param parameter: parameter name
        :param expected_value: value we expect to be set
        :param discover: perform BTS discovery before verification
        :param bts_id (enb_id): BTS instance ID
        :param alias: User defined alias used in setup_emss
        :return: None

        +----------------------------------------------------+-----------------+---------------------+------+------------+
        | Examples                                                                                                       |
        +====================================================+=================+=====================+======+============+
        | verify that eNB parameter is set to expected value | MBSFN_FDD-1-0-0 | mbsfnSessionsActive | true | bts_id=1   |
        +----------------------------------------------------+-----------------+---------------------+------+------------+
        """
        bts_id = self._opt_id(enb_id, bts_id)

        self = self._get_instance(bts_id, alias)

        if discover:
            self.run_emssim_command('discover', bts_id=bts_id, alias=alias)

        param_val = self.get_object_attributes(moc_object, parameter, bts_id=bts_id, alias=alias)[str(parameter).lower()]
        assert str(expected_value).lower() == str(param_val).lower(), \
            "eNB prameter {}:{} value: {} is not as expected: {}.".format(moc_object, parameter, param_val, expected_value)

    def configure_enb(self, config_file, rediscover=False, can_fail=True, timeout=None, name=None, skip_ro=True, skip_np=True,
                      enb_id=None, bts_id=None, alias=None):
        """
        Configure eNB using EMSS tool and configuration from yaml file.

        :param config_file: full path to yaml file with eNB configuration
        :param rediscover: perform BTS discovery before modification
        :param can_fail: Mark that the rediscover command can fail
        :param timeout: timeout to wait for rediscover command to complete
        :param name: symbolic name for the configuration plan (can be used later in deconfigure_enb)
        :param skip_ro: skip Read-Only attributes (do not rise an error on RO attribute modification)
        :param skip_np: skip not present attributes, i.e. marked in NIDD as Hidden or Not Used
        :param bts_id (enb_id): BTS instance ID
        :param alias: User defined alias used in setup_emss
        :return: None

        +------------------+--------------------------+-----------+
        |  Examples                                               |
        +==================+==========================+===========+
        | configure enb    | /home/ute/example.yaml   | bts_id=1  |
        +------------------+--------------------------+-----------+
        """
        rediscover = self._opt_bool(rediscover)
        can_fail = self._opt_bool(can_fail)
        timeout = self._opt_int(timeout)
        skip_ro = self._opt_bool(skip_ro)
        skip_np = self._opt_bool(skip_np)
        bts_id = self._opt_id(enb_id, bts_id)

        self = self._get_instance(bts_id, alias)

        if rediscover:
            self.run_emssim_command('discover', timeout=timeout, can_fail=can_fail, bts_id=bts_id, alias=alias)
        self.configure(config_file, name=name, skip_ro=skip_ro, skip_np=skip_np, bts_id=bts_id, alias=alias)
        if name:
            print('{}:: eNB-{} {} configured successfully'.format(self.__class__.__name__, bts_id, name))
        else:
            print('{}:: eNB-{} configured successfully'.format(self.__class__.__name__, bts_id))

    def change_enb_parameter_value(self, param_path, value, enb_id=None, bts_id=None, alias=None):
        """
        Change eNB parameter value using EMSS tool.

        :param param_path: path to parameter
        :param value: value to set
        :param bts_id (enb_id): BTS instance ID
        :param alias: User defined alias used in setup_emss
        :return: None

        +--------------------------+---------------------------------+-----------+----------+
        |  Examples                                                                         |
        +==========================+=================================+===========+==========+
        | change enb parameter     | LNBTS_FDD-0.act1xSrvcc          | true      | bts_id=1 |
        +--------------------------+---------------------------------+-----------+----------+
        | change enb parameter     | LNCEL-1.inactivityTimer         | 120       | bts_id=2 |
        +--------------------------+---------------------------------+-----------+----------+
        | change enb parameter     | LNBTS-1.qciTab1.qciSupp         | disable   | bts_id=1 |
        +--------------------------+---------------------------------+-----------+----------+
        | change enb parameter     | LNBTS-1.qciTab1.maxGbrDl        | 4096      | bts_id=3 |
        +--------------------------+---------------------------------+-----------+----------+
        | change enb parameter     | MBSFNCEL-3-0.mbsfnAreaInUseList | [0, 1, 2] | bts_id=1 |
        +--------------------------+---------------------------------+-----------+----------+
        """
        bts_id = self._opt_id(enb_id, bts_id)

        self = self._get_instance(bts_id, alias)

        yaml_container = YamlStructCreator(param_path=param_path, value=value).get_yaml_container()
        print('{}:: Parameters to be changed on eNB-{}: {}'.format(self.__class__.__name__, bts_id, yaml_container))
        self.configure(yaml_container, bts_id=bts_id, alias=alias)

    def deconfigure_enb(self, name=None, can_fail=True, timeout=None, enb_id=None, bts_id=None, alias=None):
        """
        Deconfigure eNB using EMSS tool.

        :param name: name of the configuration to deconfigure (used earlier in configure_enb).
                     If empty then deconfigure all previous configurations.
        :param can_fail: not used
        :param timeout: not used
        :param bts_id (enb_id): BTS instance ID
        :param alias: User defined alias used in setup_emss
        :return: None
        +------------------+------------+
        |  Examples                     |
        +==================+============+
        | deconfigure enb  | bts_id=1   |
        +------------------+------------+
        """
        bts_id = self._opt_id(enb_id, bts_id)

        self = self._get_instance(bts_id, alias)

        if name:
            self.deconfigure(name=name, bts_id=bts_id, alias=alias)
            print('{}:: eNB-{} {} deconfigured successfully'.format(self.__class__.__name__, bts_id, name))
        else:
            self.deconfigure_all(bts_id=bts_id, alias=alias)
            print('{}:: eNB-{} deconfigured successfully'.format(self.__class__.__name__, bts_id))

    def deconfigure_last_change(self, enb_id=None, bts_id=None, alias=None):
        """
            Deconfigure last parameter change eNB using EMSS tool.

            :param bts_id (enb_id): BTS instance ID
            :return: None
            +--------------------------+------------+
            |  Examples                             |
            +==========================+============+
            | deconfigure last change  | bts_id=1   |
            +--------------------------+------------+
            """
        bts_id = self._opt_id(enb_id, bts_id)

        self = self._get_instance(bts_id, alias)

        self.deconfigure_last(bts_id=bts_id, alias=alias)
        print('{}:: eNB-{} last change deconfigured successfully'.format(self.__class__.__name__, bts_id))


class YamlStructCreator(object):
    """
    Creates yaml structure for given parameter and its value.
    """

    def __init__(self, param_path, value):
        self.parameter_dict = {}
        self.current_depth = {}
        self.object_list = str(param_path).split('.')
        self.value = str(value)
        self.yaml_container = []
        self._create_yaml_container()
        print('{}:: Generated yaml structure: {}'.format(self.__class__.__name__, self.parameter_dict))

    def get_yaml_container(self):
        """

        :return: created yaml container
        """
        return self.yaml_container

    def _create_yaml_container(self):
        """

        :return: None
        """
        self._add_moc_name_to_parameter_dict()
        self._add_moc_id_to_parameter_dict()
        self._add_object_to_parameter_dict()
        self.yaml_container.append(self.parameter_dict)

    def _add_moc_name_to_parameter_dict(self):
        """

        :return: None
        """
        moc_name = re.sub('-.*', '', self.object_list[0])
        self.parameter_dict['MOC'] = moc_name

    def _add_moc_id_to_parameter_dict(self):
        """

        :return: None
        """
        moc_id = re.sub('^.*?-', '', self.object_list[0])
        self.parameter_dict['ID'] = moc_id

    def _add_object_to_parameter_dict(self):
        """

        :return: None
        """
        self.current_depth = self.parameter_dict
        for moc_object in self.object_list[1:]:
            if self.object_list.index(moc_object) == len(self.object_list) - 1:
                self._add_value_to_parameter_dict(moc_object)
            else:
                self.parameter_dict[moc_object] = [{}]
                self.current_depth = self.current_depth[moc_object][0]

    def _add_value_to_parameter_dict(self, moc_object):
        """

        :param moc_object:
        :return: None
        """
        if re.search(r'\[.*\]', self.value):
            values_list = re.sub(r'\[|\]|\s', '', self.value).split(',')
            self.current_depth.setdefault(moc_object, values_list)
        else:
            self.current_depth[moc_object] = self.value
